def max_k_upper_bound(N):
    if N < 2:
        return 0
    E = N * (N - 1) / 2
    return int(E / (N - 1))

print(f"N=3: {max_k_upper_bound(3)}")
print(f"N=5: {max_k_upper_bound(5)}")
print(f"N=7: {max_k_upper_bound(7)}")
